package pro.celikom.nativeprobe.identitydiag;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.json.*;
final class IdentityCache {
 final File file;final LinkedHashMap<String,JSONObject> entries=new LinkedHashMap<>();
 IdentityCache(File file){this.file=file;try{if(!file.exists()||file.length()>4194304)return;ByteArrayOutputStream b=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(file)){byte[] data=new byte[8192];int n;while((n=in.read(data))!=-1){if(b.size()+n>4194304)return;b.write(data,0,n);}}JSONObject root=new JSONObject(new String(b.toByteArray(),StandardCharsets.UTF_8));if(root.optInt("schema")!=1)return;JSONArray rows=root.optJSONArray("albums");long now=System.currentTimeMillis();if(rows!=null)for(int i=0;i<Math.min(32,rows.length());i++){JSONObject e=rows.optJSONObject(i);if(e==null)continue;String id=e.optString("albumId");long age=now-e.optLong("savedAtMs",0);if(id.matches("\\d{1,15}")&&age>=0&&age<=7*86400000L&&e.optJSONArray("tracks")!=null)entries.put(id,e);}}catch(Exception e){LogStore.error("identity_cache_load",e);}}
 Map<String,List<Map<String,Object>>> load(){Map<String,List<Map<String,Object>>> out=new LinkedHashMap<>();for(Map.Entry<String,JSONObject> entry:entries.entrySet()){List<Map<String,Object>> tracks=new ArrayList<>();JSONArray rows=entry.getValue().optJSONArray("tracks");for(int i=0;i<Math.min(rows.length(),1000);i++){JSONObject t=rows.optJSONObject(i);if(t==null)continue;tracks.add(LogStore.map("catalogueTrackId",t.optString("catalogueTrackId"),"displayTitle",t.optString("displayTitle"),"title",t.optString("title"),"version",t.optString("version"),"artist",t.optString("artist"),"durationMs",t.optLong("durationMs",-1)));}out.put(entry.getKey(),tracks);}return out;}
 void save(String id,List<Map<String,Object>> tracks){try{entries.remove(id);JSONArray rows=new JSONArray();for(Map<String,Object> t:tracks)rows.put(new JSONObject(t));entries.put(id,new JSONObject().put("albumId",id).put("savedAtMs",System.currentTimeMillis()).put("tracks",rows));while(entries.size()>32)entries.remove(entries.keySet().iterator().next());byte[] bytes=serialize();while(bytes.length>4194304&&entries.size()>1){entries.remove(entries.keySet().iterator().next());bytes=serialize();}if(bytes.length>4194304)return;File temp=new File(file.getPath()+".tmp");try(FileOutputStream out=new FileOutputStream(temp)){out.write(bytes);out.getFD().sync();}if(!temp.renameTo(file))throw new IOException("Atomic cache replacement failed");}catch(Exception e){LogStore.error("identity_cache_save",e);}}
 byte[] serialize()throws Exception{return new JSONObject().put("schema",1).put("albums",new JSONArray(entries.values())).toString().getBytes(StandardCharsets.UTF_8);}
}
